def add_binary(a, b):
    i, j, carry = len(a) - 1, len(b) - 1, 0
    out = []
    while i >= 0 or j >= 0 or carry:
        total = carry
        if i >= 0:
            total += int(a[i])
        if j >= 0:
            total += int(b[j])
        carry, bit = divmod(total, 2)
        out.append(str(bit))
        i -= 1
        j -= 1
    return "".join(reversed(out))

